            cardInternalId,
            diffSelection,
            fallbackAnchorElement: createFallbackAnchor(anchorElement),
            id: `card-details-popup-${this.nextId}`,
            kind: 'card-details',
        }
        this.nextId += 1
        this.setEntries([...this.entries, entry])
    }

    private removeEntries(shouldRemove: (entry: CardPopupEntry) => boolean) {
        const removedEntries = this.entries.filter(shouldRemove)
        if (removedEntries.length === 0) return

        if (removedEntries.some(({ kind }) => kind === 'sequence')) cardSequenceDraftService.close();
        removedEntries.forEach(({ fallbackAnchorElement }) => fallbackAnchorElement.remove())
        this.setEntries(this.entries.filter((entry) => !shouldRemove(entry)))
    }

    private replaceEntry(replacement: CardPopupEntry) {
        this.setEntries(this.entries.map((entry) => entry.id === replacement.id ? replacement : entry))
    }

    private requireCardDetails(id: string) {
        const entry = this.entries.find((candidate): candidate is CardDetailsPopupEntry => (
            candidate.id === id && candidate.kind === 'card-details'
        ))
        if (!entry) throw new Error(`Card details popup does not exist: ${id}`)

        return entry
    }

    private setEntries(entries: CardPopupEntry[]) {
        this.entries = entries
        this.reconcileMobileBackDismissRegistrations()
        this.dispatchEvent(new Event(CARD_POPUPS_CHANGED_EVENT))
    }

    private reconcileMobileBackDismissRegistrations() {
        const requiredRegistrationCount = this.mobileBackDismissEnabled ? this.entries.length : 0
        const obsoleteRegistrationIds = this.mobileBackDismissRegistrationIds.slice(requiredRegistrationCount)
        this.mobileBackDismissRegistrationIds = this.mobileBackDismissRegistrationIds.slice(0, requiredRegistrationCount)
        obsoleteRegistrationIds.forEach((registrationId) => this.mobileBackDismissService.unregister(registrationId))

        const missingRegistrationCount = requiredRegistrationCount - this.mobileBackDismissRegistrationIds.length
        const newRegistrationIds = Array.from({ length: missingRegistrationCount }, () => {
            const registrationId = `${MOBILE_BACK_DISMISS_REGISTRATION_PREFIX}-${this.nextMobileBackDismissRegistrationId}`
            this.nextMobileBackDismissRegistrationId += 1
            this.mobileBackDismissService.register(registrationId, this.closeTopPopup)

            return registrationId
        })
        this.mobileBackDismissRegistrationIds = [...this.mobileBackDismissRegistrationIds, ...newRegistrationIds]
    }
}

export const cardPopupService = register(
    'cardPopupService',
    new CardPopupService(dataService, mobileBackDismissService),
)

export function subscribeCardPopups(onStoreChange: () => void) {
    cardPopupService.addEventListener(CARD_POPUPS_CHANGED_EVENT, onStoreChange)

    return () => cardPopupService.removeEventListener(CARD_POPUPS_CHANGED_EVENT, onStoreChange)
}

/** Subscribes to focus requests for one popup entry. */
export function subscribeCardPopupFocusRequest(entryId: string, listener: () => void) {
    const eventType = `${CARD_POPUP_FOCUS_REQUESTED_EVENT_PREFIX}${entryId}`
    cardPopupService.addEventListener(eventType, listener)

    return () => cardPopupService.removeEventListener(eventType, listener)
}

import { useLayoutEffect, useState, useSyncExternalStore } from 'react';
import { ActionPopupFrame } from './action_popup_frame';
import { ActionPopupSession } from './action_popup_session';
import { ActionPopupSessionService } from './action_popup_session_service';
import type { ActionPopupContentProps } from './action_popup_types';

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_frame';

/** Keeps the popup surface and agent editor mounted while services switch action bindings. */
export function ActionPopupContent(props: ActionPopupContentProps) {
    const { action, assignmentContext, historicalEntries, initialConversationPath, initialRunId } = props;
    const [service] = useState(() => new ActionPopupSessionService());
    const selected = useSyncExternalStore(service.subscribe, service.getSnapshot, service.getSnapshot);
    useLayoutEffect(() => {
        service.select(action, assignmentContext, initialRunId, initialConversationPath, historicalEntries);
    }, [action, assignmentContext, historicalEntries, initialConversationPath, initialRunId, service]);
    useLayoutEffect(() => () => service.dispose(), [service]);
    if (!selected) return null;

    const contentProps = { ...props, action: selected.action, assignmentContext: selected.context };
    const { bindingStore, conversationSearchService, conversationStore } = selected.runtime;
    return (
        <ActionPopupFrame bindingStore={bindingStore} contentProps={contentProps}
            conversationSearchService={conversationSearchService} conversationStore={conversationStore}>
            <ActionPopupSession {...contentProps} runtime={selected.runtime} />
        </ActionPopupFrame>
    );
}

